-- Here's the dialog that pops up if the player has never worked for this alchemist before:
newChat{ id="welcome",
	text = _t[[#LIGHT_GREEN#*A dwarf in stained, battered mail armor opens the door.*#WHITE#
Say, you interested in dismembering stuff and getting paid?]],
	answers = {
		{_t"Always.", jump="ominous"},
		{_t"[leave]"},
	}
}

newChat{ id="ominous",
	text = _t[[By the corpses of the gods, I love adventurers. Was about to become one myself when it suddenly hit me. And by "it" I mean "my wife." Har!]],
	answers = {
		{_t"What do you propose?", jump="proposal"},
	}
}

newChat{ id="proposal",
	text = _t[[I propose that I give you a list of monster parts to fetch, then you go and fetch them, then I make some blindingly amazing brews with said monster parts, then I get accepted into the Brotherhood of Alchemists.]],
	answers = {
		{_t"Sounds like a plan.", jump="help"},
	}
